public class FastDateFormat_applyRules_TriageGen1Test {

    /**
     * Since applyRules is protected, we use a subclass or reflection to test it.
     * Given the structure, we will use reflection to inject the mRules array 
     * to control the behavior of the Rule objects.
     */
    @Test
    public void testApplyRules_Success() throws Exception {
        // Setup: Create a FastDateFormat instance via a public constructor/factory
        // We use a pattern that ensures rules are initialized
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy-MM-dd");

        // Mock the Rules
        Rule rule1 = mock(Rule.class);
        Rule rule2 = mock(Rule.class);

        // Setup behavior for rules to append specific strings
        doAnswer(invocation -> {
            StringBuffer sb = invocation.getArgument(0);
            sb.append("Rule1");
            return null;
        }).when(rule1).appendTo(any(StringBuffer.class), any(Calendar.class));

        doAnswer(invocation -> {
            StringBuffer sb = invocation.getArgument(0);
            sb.append("Rule2");
            return null;
        }).when(rule2).appendTo(any(StringBuffer.class), any(Calendar.class));

        // Inject the mocks into the private field mRules using reflection
        Field rulesField = FastDateFormat.class.getDeclaredField("mRules");
        rulesField.setAccessible(true);
        Rule[] mockRules = new Rule[]{rule1, rule2};
        rulesField.set(fdf, mockRules);

        // Test parameters
        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer("Start-");

        // Execute the protected method via reflection
        java.lang.reflect.Method applyRulesMethod = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        applyRulesMethod.setAccessible(true);
        StringBuffer result = (StringBuffer) applyRulesMethod.invoke(fdf, calendar, buf);

        // Verify results
        assertEquals("Start-Rule1Rule2", result.toString());
        verify(rule1, times(1)).appendTo(buf, calendar);
        verify(rule2, times(1)).appendTo(buf, calendar);
    }

    @Test
    public void testApplyRules_EmptyRules() throws Exception {
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");

        // Inject an empty rules array
        Field rulesField = FastDateFormat.class.getDeclaredField("mRules");
        rulesField.setAccessible(true);
        rulesField.set(fdf, new Rule[0]);

        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer("Initial");

        java.lang.reflect.Method applyRulesMethod = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        applyRulesMethod.setAccessible(true);
        StringBuffer result = (StringBuffer) applyRulesMethod.invoke(fdf, calendar, buf);

        // Verify that nothing was appended
        assertEquals("Initial", result.toString());
    }

    @Test
    public void testApplyRules_SingleRule() throws Exception {
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");

        Rule rule = mock(Rule.class);
        doAnswer(invocation -> {
            StringBuffer sb = invocation.getArgument(0);
            sb.append("Applied");
            return null;
        }).when(rule).appendTo(any(StringBuffer.class), any(Calendar.class));

        Field rulesField = FastDateFormat.class.getDeclaredField("mRules");
        rulesField.setAccessible(true);
        rulesField.set(fdf, new Rule[]{rule});

        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer("Pre-");

        java.lang.reflect.Method applyRulesMethod = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        applyRulesMethod.setAccessible(true);
        StringBuffer result = (StringBuffer) applyRulesMethod.invoke(fdf, calendar, buf);

        assertEquals("Pre-Applied", result.toString());
        verify(rule, times(1)).appendTo(buf, calendar);
    }
}
